<?php
if (!defined("SUAVE_RAIZ")) { http_response_code(404); exit; } use Suave\Interfaz as V;
$from=(string)($_GET['desde']??$month.'-01');$until=(string)($_GET['hasta']??date('Y-m-t',strtotime($month.'-01')));Suave\Numeros::date($from,'Desde');Suave\Numeros::date($until,'Hasta');
if($from>$until)throw new Suave\ErrorUsuario('El inicio del intervalo debe ser anterior a su final.');
$search=Suave\Numeros::text($_GET['buscar']??'','Búsqueda',100,false);$query=[$from.' 00:00:00',date('Y-m-d',strtotime($until.' +1 day')).' 00:00:00'];$where='creado_en>=? AND creado_en<?';if($search!==''){$where.=' AND (evento LIKE ? OR referencia LIKE ? OR motivo LIKE ?)';array_push($query,'%'.$search.'%','%'.$search.'%','%'.$search.'%');}
$count=(int)$db->value('SELECT COUNT(*) FROM actividad WHERE '.$where,$query);$pages=max(1,(int)ceil($count/20));$number=max(1,min($pages,(int)($_GET['pagina']??1)));$events=$db->all('SELECT * FROM actividad WHERE '.$where.' ORDER BY id DESC LIMIT 20 OFFSET '.(($number-1)*20),$query);
$selected=isset($_GET['evento_id'])?$db->one('SELECT * FROM actividad WHERE id=?',[(int)$_GET['evento_id']]):null;
$labelMap=['total_centavos'=>'Importe total','importe_centavos'=>'Importe','precio_centavos'=>'Precio','cantidad_milesimas'=>'Cantidad','producto_nombre'=>'Nombre histórico del producto','producto_clave'=>'Producto actual','sucursal_codigo'=>'Código de sucursal','sucursal_nombre'=>'Nombre de sucursal','creado_en'=>'Fecha de guardado','actualizado_en'=>'Último cambio','validado_centavos'=>'Importe validado','sha256'=>'Integridad del archivo','datos_json'=>'Datos conservados'];
$flatten=function(mixed $value,string $prefix='')use(&$flatten,$labelMap):array{$result=[];if(is_array($value)){foreach($value as $key=>$item){$label=is_int($key)?'Renglón '.($key+1):($labelMap[$key]??ucfirst(str_replace('_',' ',(string)$key)));$path=$prefix===''?$label:$prefix.' / '.$label;if(is_array($item))$result+=$flatten($item,$path);else{$result[$path]=is_bool($item)?($item?'Sí':'No'):($item===null?'Sin dato':(str_ends_with((string)$key,'_centavos')?Suave\Numeros::currency((int)$item):((string)$key==='cantidad_milesimas'?rtrim(rtrim(Suave\Numeros::input((int)$item,3),'0'),'.'):(string)$item)));}}}elseif($value!==null)$result[$prefix?:'Valor']=(string)$value;return $result;};
?>
<div class="page-heading"><div><h1>Actividad</h1><p>Consulta qué cambió, cuándo y a qué documento corresponde.</p></div></div>
<form method="get" class="filters"><?=V::hidden('p','actividad')?><?=V::hidden('mes',$month)?><?=V::input('Desde','desde',$from,'date',['required'=>true])?><?=V::input('Hasta','hasta',$until,'date',['required'=>true])?><?=V::input('Buscar evento o referencia','buscar',$search,'search',['maxlength'=>100])?><button type="submit" class="button">Buscar</button></form>
<?php if(!$events):?><?=V::empty('Todavía no hay actividad en este intervalo','Los eventos aparecen al guardar operaciones. Consultar pantallas y escribir sin guardar no genera cambios.')?><?php else:?>
<div class="table-wrap"><table><thead><tr><th>Fecha y hora</th><th>Evento</th><th>Referencia</th><th>Detalle</th></tr></thead><tbody><?php foreach($events as $event):$target=match($event['tipo']){'entrega'=>'ver_entrega','reporte'=>'reporte_version','caso'=>'caso','cierre','periodo'=>'cierre','producto','sucursal'=>'catalogos',default=>'conciliacion'};$args=match($event['tipo']){'entrega','reporte','caso'=>['id'=>$event['registro_id']],'periodo'=>['mes'=>$event['registro_id']],'cierre'=>['mes'=>substr($event['referencia'],0,7)],'producto'=>['editar_producto'=>$event['registro_id']],'sucursal'=>['editar_sucursal'=>$event['registro_id']],default=>['mes'=>substr($event['referencia'],0,7)]};?><tr><td><?=V::h($event['creado_en'])?></td><td><?=V::h($event['evento'])?></td><td><?=$w->link($event['referencia'],$target,$args,'text-link')?></td><td><?=$w->link('Ver cambio','actividad',['desde'=>$from,'hasta'=>$until,'buscar'=>$search,'pagina'=>$number,'evento_id'=>$event['id']],'text-link')?></td></tr><?php endforeach?></tbody></table></div>
<div class="pagination"><span><?=$count?> eventos · página <?=$number?> de <?=$pages?></span><div class="action-row"><?php if($number>1):?><?=$w->link('Anterior','actividad',['desde'=>$from,'hasta'=>$until,'buscar'=>$search,'pagina'=>$number-1])?><?php endif?><?php if($number<$pages):?><?=$w->link('Siguiente','actividad',['desde'=>$from,'hasta'=>$until,'buscar'=>$search,'pagina'=>$number+1])?><?php endif?></div></div><?php endif?>
<?php if($selected):$before=$flatten(Suave\Datos::decode($selected['antes_json']));$after=$flatten(Suave\Datos::decode($selected['despues_json']));$keys=array_unique(array_merge(array_keys($before),array_keys($after)));?><section class="section-block"><h2><?=V::h($selected['evento'])?> · <?=V::h($selected['referencia'])?></h2><p><?=V::h($selected['creado_en'])?></p><p><strong>Motivo:</strong> <?=V::h($selected['motivo'])?></p><div class="table-wrap"><table><thead><tr><th>Dato</th><th>Antes</th><th>Después</th></tr></thead><tbody><?php $shown=0;foreach($keys as $key):if(($before[$key]??null)===($after[$key]??null))continue;if(++$shown>200)break;?><tr><td><?=V::h($key)?></td><td class="wrap-text"><?=V::h($before[$key]??'—')?></td><td class="wrap-text"><?=V::h($after[$key]??'—')?></td></tr><?php endforeach?></tbody></table></div></section><?php endif?>
<p class="hint">Actividad conserva los cambios y sus motivos. El sistema no solicita cuentas ni registra quién realizó cada acción.</p>
